// Transform input payload (Supabase order trigger) into Zoho Sales Order JSON schema
const input = $input.first().json;
const order = input.order;
const itemsList = input.items || [];

// Zoho API sales order schema mapping
const zohoSalesOrder = {
  customer_id: order.b2b_flag ? order.company_zoho_contact_id : "RETAIL_WALKIN_CONTACT_ID", 
  salesorder_number: order.order_number,
  date: new Date(order.created_at).toISOString().split('T')[0],
  shipment_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], 

  custom_fields: [
    { label: "Channel Origin", value: "Storefront Web" },
    { label: "B2B flag", value: String(order.b2b_flag) },
    { label: "GSTIN", value: order.gstin || "" }
  ],

  line_items: itemsList.map(item => {
    return {
      sku: item.sku,
      name: item.name,
      rate: Number(item.unit_price),
      quantity: Number(item.quantity),
      tax_percentage: Number(item.tax_rate),
      discount: Number(item.discount_amount),
      description: `SKU: ${item.sku}`
    };
  }),

  shipping_charge: Number(order.shipping_charge),
  discount: Number(order.discount_amount),

  billing_address: {
    address: order.billing_address?.line1 || "",
    street2: order.billing_address?.line2 || "",
    city: order.billing_address?.city || "",
    state: order.billing_address?.state || "",
    zip: order.billing_address?.postal_code || "",
    country: order.billing_address?.country || "India"
  },

  shipping_address: {
    address: order.shipping_address?.line1 || "",
    street2: order.shipping_address?.line2 || "",
    city: order.shipping_address?.city || "",
    state: order.shipping_address?.state || "",
    zip: order.shipping_address?.postal_code || "",
    country: order.shipping_address?.country || "India"
  }
};

if (order.b2b_flag && order.zoho_pricebook_id) {
  zohoSalesOrder.pricebook_id = order.zoho_pricebook_id;
}

return [{ json: zohoSalesOrder }];

